import re
B='/home/claude/customer-support-prd/prd/'; S=B+'03 - PRD Sections/'
def rw(p,f):
    s=open(p,encoding='utf-8').read(); t=f(s); assert t!=s,p; open(p,'w',encoding='utf-8').write(t)
def R(s,a,b):
    assert a in s, a[:80]; return s.replace(a,b)
def front(s,old,new,note):
    s=R(s,f'version: {old}\n',f'version: {new}\n'); s=re.sub(r'last_updated: \S+','last_updated: 2026-11-20',s,1)
    return re.sub(r'(change_note: ".*?)"\n', lambda m: m.group(1)+f' · {new} — {note}"\n', s, count=1)
HINTS='«قدیمی شده — دوباره تأیید یا اصلاح کنید» · «منبع ندارد — موجودی را ثبت کنید» · «اطلاعات متعارض — رکورد درست را انتخاب کنید» · «زمان تأیید نامعتبر — دوباره تأیید کنید» · «آستانه تنظیم نشده — آستانه اعتبار را در تنظیمات تعیین کنید»'
INTRO='«دستیار درباره این محصولات به مشتری جواب قطعی نداده است؛ داده را تأیید یا اصلاح کنید تا دوباره جواب بدهد.»'
EMPTY='«موردی منتظر بررسی نیست؛ دستیار برای همه موجودی‌ها داده معتبر دارد.»'
def ep05(s):
    s=front(s,'1.2','1.3','CH-53: متن رابط فهرست (منو «بررسی موجودی»، توضیح، راهنمای کار هر نوع، نام ستون‌ها، حالت خالی) و «بستن بدون اصلاح» (DEC-308)')
    s=R(s,'| ‏تعداد رخداد | ‏چند بار مشتری‌ها به این مورد خورده‌اند | ‏DEC-65 |','| ‏تعداد رخداد | ‏چند بار مشتری‌ها به این مورد خورده‌اند؛ سرستون در رابط: «مشتری‌هایی که پرسیدند» | ‏DEC-65؛ DEC-308 |')
    s=R(s,'| ‏آخرین رخداد | ‏زمان نسبی | ‏04-00 §0.4 |','| ‏آخرین رخداد | ‏زمان نسبی؛ سرستون در رابط: «آخرین پرسش» | ‏04-00 §0.4؛ DEC-308 |')
    s=R(s,'| ‏مورد بازی نیست | ‏«مغایرت بازی نیست.» |','| ‏مورد بازی نیست | ‏'+EMPTY+' |')
    s=R(s,'| ‏عنوان | ‏«موجودی‌هایی که دستیار نتوانست قطعی جواب بدهد» |','| ‏منو | ‏«بررسی موجودی» (DEC-308) |\n| ‏عنوان | ‏«موجودی‌هایی که دستیار نتوانست قطعی جواب بدهد» |\n| ‏توضیح زیر عنوان | ‏'+INTRO+' (DEC-308) |')
    s=R(s,'«قدیمی شده» **(CH-31؛ VL-09)** |','«قدیمی شده» **(CH-31؛ VL-09)** |\n| ‏راهنمای کار زیر هر برچسب | ‏'+HINTS+' (DEC-308؛ برچسب‌های VL-09 تغییر نکرد) |')
    s=R(s,'| ‏خالی | ‏«مغایرت بازی نیست.» |','| ‏خالی | ‏'+EMPTY+' (DEC-308) |')
    s=R(s,'«هنوز درست است — تأیید دوباره» · «بستن مغایرت بدون اصلاح» | ‏FR-10؛ DEC-85 |','«هنوز درست است — تأیید دوباره» · «بستن بدون اصلاح» | ‏FR-10؛ DEC-85؛ DEC-308 |')
    s=re.sub(r'(\| ‏1\.2 \| ‏2026-11-12 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.3 | ‏2026-11-20 | ‏US-05-01: سرستون‌های رابط «مشتری‌هایی که پرسیدند» و «آخرین پرسش»؛ متن منو، توضیح زیر عنوان، راهنمای کار هر نوع و حالت خالی. US-05-02: کنش «بستن بدون اصلاح». داده، رفتار، ترتیب و برچسب‌های VL-09 تغییر نکرد | ‏CH-53؛ DEC-308 |\n', s, count=1)
    return s
def c05(s):
    s=front(s,'1.3','1.4','CH-53: متن رابط SCR-20 تا SCR-23 و W1 — «بررسی موجودی»، راهنمای کار هر نوع، «منتظر تأیید» (DEC-307، DEC-308)')
    s=R(s,'I -- "بستن مغایرت بدون اصلاح" --> W1','I -- "بستن بدون اصلاح" --> W1')
    s=R(s,'| ‏R0-a منو | ‏مالک: «مغایرت‌ها ([۳])»','| ‏R0-a منو | ‏مالک: «بررسی موجودی ([۳])» (DEC-308)')
    s=R(s,'| ‏R1 عنوان | ‏عنوان + شمار موارد باز | — | ‏US-05-01 | ‏«عنوان» ← US-05-01 |','| ‏R1 عنوان | ‏عنوان + یک خط توضیح و ترتیب؛ شمار موارد باز در زبانه «باز» و شمارنده منو | — | ‏US-05-01؛ DEC-308 | ‏«عنوان»، «توضیح زیر عنوان» ← US-05-01 |')
    s=R(s,'| ‏نوع | ‏برچسب VL-09 | ‏DEC-82 |','| ‏نوع | ‏برچسب VL-09 و زیر آن راهنمای کار به خط کوچک | ‏DEC-82؛ DEC-308 |')
    s=R(s,'| ‏تعداد رخداد | ‏عدد | ‏DEC-65 |','| ‏تعداد رخداد | ‏سرستون «مشتری‌هایی که پرسیدند»؛ عدد | ‏DEC-65؛ DEC-308 |')
    s=R(s,'| ‏آخرین رخداد | ‏نسبی | ‏04-00 §0.4 |','| ‏آخرین رخداد | ‏سرستون «آخرین پرسش»؛ نسبی | ‏04-00 §0.4؛ DEC-308 |')
    s=R(s,'با برچسب «پیش‌نویس — در پاسخ استفاده نمی‌شود» |','با برچسب «منتظر تأیید — دستیار تا تأیید از آن استفاده نمی‌کند» (DEC-307) |')
    s=s.replace('«بستن مغایرت بدون اصلاح»','«بستن بدون اصلاح»')
    s=R(s,'زمان آخرین تأیید · برچسب «پیش‌نویس دارد» |','زمان آخرین تأیید · برچسب «منتظر تأیید» با راهنمای «تا تأیید نشود، دستیار از آن استفاده نمی‌کند» (DEC-307) |')
    s=R(s,'برچسب «منقضی» · برچسب «پیش‌نویس دارد» |','برچسب «منقضی» · برچسب «منتظر تأیید» (DEC-307) |')
    s=R(s,'| ‏مغایرت باز و بسته · میانه زمان بازماندن مغایرت ·','| ‏موارد بررسی موجودی باز و بسته · میانه زمان تا بررسی (DEC-308) ·')
    s=R(s,'| ‏W1 بستن مغایرت بدون اصلاح | ‏SCR-21 | ‏کادر دلیل (الزامی) | ‏«بستن مغایرت» ·','| ‏W1 بستن بدون اصلاح | ‏SCR-21 | ‏کادر دلیل (الزامی) | ‏«بستن مورد» (DEC-308) ·')
    s=R(s,'| ‏SCR-21 R3 | ‏«پیش‌نویس — در پاسخ استفاده نمی‌شود» | ‏قاعده مشترک EP-05 شماره ۱ |',
        '| ‏SCR-21 R3 | ‏«منتظر تأیید — دستیار تا تأیید از آن استفاده نمی‌کند» | ‏قاعده مشترک EP-05 شماره ۱؛ DEC-307 |\n| ‏SCR-22 و SCR-23 R3 | ‏برچسب «منتظر تأیید»؛ راهنما «تا تأیید نشود، دستیار از آن استفاده نمی‌کند» | ‏DEC-307 |\n| ‏منو و SCR-20 | ‏منو «بررسی موجودی» · توضیح زیر عنوان، راهنمای کار هر نوع، سرستون‌ها و حالت خالی ← US-05-01 | ‏DEC-308 |')
    s=R(s,'| ‏DEC-274 | ‏بنر ۳ ← کارت «راه‌اندازی فروشگاه»','| ‏DEC-307 | ‏برچسب «منتظر تأیید» جای «پیش‌نویس دارد» در SCR-22 و SCR-23 (با راهنما) و در SCR-21 R3 (CH-53) |\n| ‏DEC-308 | ‏متن رابط بررسی موجودی: منو «بررسی موجودی»، توضیح زیر عنوان SCR-20، راهنمای کار زیر برچسب هر نوع، سرستون‌های «مشتری‌هایی که پرسیدند» و «آخرین پرسش»، حالت خالی، «بستن بدون اصلاح» و «بستن مورد»؛ داده و رفتار تغییر نکرد (CH-53) |\n| ‏DEC-274 | ‏بنر ۳ ← کارت «راه‌اندازی فروشگاه»')
    s=re.sub(r'(\| ‏1\.3 \| ‏2026-11-16 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.4 | ‏2026-11-20 | ‏متن رابط: منو «بررسی موجودی»؛ SCR-20 توضیح، راهنمای کار هر نوع، سرستون‌ها؛ SCR-21 R3 و SCR-22/23 برچسب «منتظر تأیید»؛ «بستن بدون اصلاح» و W1 «بستن مورد»؛ نام کارت گزارش گروه ۶. چیدمان، داده و رفتار تغییر نکرد | ‏CH-53؛ DEC-307، DEC-308 |\n', s, count=1)
    return s
def gl(s):
    s=front(s,'1.4','1.5','CH-53: برچسب‌های رابط «منتظر تأیید» و «بررسی موجودی» (DEC-307، DEC-308)')
    s=R(s,'| ‏پیش‌نویس | ‏Draft | ‏تغییر ذخیره‌شده ولی تأییدنشده؛ هرگز وارد پاسخ نمی‌شود | ‏— | ‏ND-12 |','| ‏پیش‌نویس | ‏Draft | ‏تغییر ذخیره‌شده ولی تأییدنشده؛ هرگز وارد پاسخ نمی‌شود | ‏برچسب در فهرست‌ها و نمای ویرایش: «منتظر تأیید» | ‏ND-12؛ DEC-307 |')
    s=R(s,'| ‏فهرست مغایرت‌ها | ‏Discrepancy list | ‏صفحه SCR-20؛ تنها راه باخبرشدن مالک از مغایرت (اعلان نداریم) | ‏— | ‏DEC-35؛ ND-37 |','| ‏فهرست مغایرت‌ها | ‏Discrepancy list | ‏صفحه SCR-20؛ تنها راه باخبرشدن مالک از مغایرت (اعلان نداریم) | ‏در رابط: منو «بررسی موجودی»، عنوان «موجودی‌هایی که دستیار نتوانست قطعی جواب بدهد»؛ «مغایرت» نام مرجع در اسناد است و در رابط فروشگاه دیده نمی‌شود | ‏DEC-35؛ ND-37؛ DEC-308 |')
    s=re.sub(r'(\| ‏1\.4 \| ‏2026-11-20 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.5 | ‏2026-11-20 | ‏**CH-53 (DEC-307، DEC-308):** مدخل «پیش‌نویس» با برچسب رابط «منتظر تأیید»؛ مدخل «فهرست مغایرت‌ها» با نام منو و عنوان رابط. هیچ تعریف یا نام مرجعی تغییر نکرد |\n', s, count=1)
    return s
def mi(s):
    s=R(s,'version: 1.9\n','version: 1.10\n')
    s=R(s,'| ‏1.9 | ‏2026-11-20 | ‏آزمون تیمی دوم؛ CH-52 (با همگام‌سازی DEC-303) |','| ‏1.10 | ‏2026-11-20 | ‏متن رابط بررسی موجودی؛ CH-53 |')
    s=R(s,'| ‏PRD-04-EP05 - Reference Data Management | ‏Approved | ‏**1.2 (CH-31، CH-41)** | ‏2026-11-12 |','| ‏PRD-04-EP05 - Reference Data Management | ‏Approved | ‏**1.3 (CH-31، CH-41، CH-53)** | ‏2026-11-20 |')
    s=R(s,'| ‏PRD-05c - Store Management Panel | ‏Approved | ‏**1.3 (CH-48)** | ‏2026-11-16 |','| ‏PRD-05c - Store Management Panel | ‏Approved | ‏**1.4 (CH-48، CH-53)** | ‏2026-11-20 |')
    s=R(s,'| ‏PRD-15 - Glossary | ‏Approved | ‏**1.4 (CH-31، CH-37، CH-41 تا CH-45، CH-52)** |','| ‏PRD-15 - Glossary | ‏Approved | ‏**1.5 (CH-31، CH-37، CH-41 تا CH-45، CH-52، CH-53)** |')
    s=R(s,'| ‏DEC-306 | ‏اسکرول‌بار کادر نوشتن مشتری فقط وقتی متن از ۴ خط بیشتر شود. | ‏2026-11-20 | ‏PRD-05a | ‏CH-52 |\n',
        '| ‏DEC-306 | ‏اسکرول‌بار کادر نوشتن مشتری فقط وقتی متن از ۴ خط بیشتر شود. | ‏2026-11-20 | ‏PRD-05a | ‏CH-52 |\n| ‏DEC-307 | ‏**برچسب «منتظر تأیید»** جای «پیش‌نویس دارد» در جدول‌های محصولات و دانش و سیاست، با راهنمای «تا تأیید نشود، دستیار از آن استفاده نمی‌کند»؛ همین متن در نمای اصلاح (SCR-21 R3). دکمه «ذخیره پیش‌نویس» و قاعده دوگامی تغییر نکرد. | ‏2026-11-20 | ‏PRD-05c؛ PRD-15 | ‏CH-53 |\n| ‏DEC-308 | ‏**متن رابط بررسی موجودی:** منو «بررسی موجودی»؛ توضیح زیر عنوان SCR-20؛ راهنمای کار زیر برچسب هر نوع (برچسب‌های VL-09 تغییر نکرد)؛ سرستون‌های «مشتری‌هایی که پرسیدند» و «آخرین پرسش»؛ حالت خالی تازه؛ «بستن بدون اصلاح» و «بستن مورد». «مغایرت» نام مرجع اسناد می‌ماند. داده و رفتار تغییر نکرد. | ‏2026-11-20 | ‏PRD-04-EP05؛ PRD-05c؛ PRD-15 | ‏CH-53 |\n')
    s=re.sub(r'(\| ‏CH-52 \| ‏2026-11-20 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏CH-53 | ‏2026-11-20 | ‏**متن رابط پنل فروشگاه (بازبینی طراحی صفحه مغایرت‌ها):** DEC-307 و DEC-308 ثبت شد؛ PRD-04-EP05 1.3، PRD-05c 1.4، PRD-15 1.5. فقط متن رابط؛ داده، رفتار، ترتیب و فهرست‌های VL تغییر نکرد. پروتوتایپ و بوم به‌روز شد. | ‏PRD-04-EP05، PRD-05c، PRD-15 |\n', s, count=1)
    return s
rw(S+'PRD-04-EP05 - Reference Data Management.md',ep05); rw(S+'PRD-05c - Store Management Panel.md',c05); rw(S+'PRD-15 - Glossary.md',gl); rw(B+'00 - Master Project Index.md',mi)
print('ok')
